def firstExitAdmittedChoices {α : Type*} (k : ℕ)
    (parent : Bool → List α → Bool) (pre : List α) (positive : Bool)
    (carrier : List α) : List (List α)

private theorem admittedChoices_zero {α : Type*}
    (parent : Bool → List α → Bool) (pre carrier : List α) (positive : Bool) :
    firstExitAdmittedChoices 0 parent pre positive carrier = [[]]

private theorem admittedTuple_ofFn {k : ℕ} {chosen : List ℕ}
    (hc : chosen.length = k) :
    List.ofFn (primeHistoryTuple k chosen.reverse) = chosen

theorem primeHistoryTuple_ofFn {k : ℕ} {history : List ℕ}
    (hlen : history.length = k) :
    List.ofFn (primeHistoryTuple k history) = history.reverse

theorem primeHistoryTuple_reverse_ofFn {k : ℕ} {history : List ℕ}
    (hlen : history.length = k) :
    (List.ofFn (primeHistoryTuple k history)).reverse = history

